#include <stdio.h>
#include "sda_random_driver.h"
#include "sda_epsilon.h"
#include "sda_falcon_bkz.h"
#include "sda_generation.h"
#include "sda_metrics.h"
#include <errno.h>
#include <string.h>
#include <sys/stat.h>

static void print_u128(FILE *f, sda_u128 x) { char b[64]; sda_print_u128(x,b,sizeof b); fputs(b,f); }
static void print_c_u128(FILE *f,sda_u128 x){fprintf(f,"(((sda_u128)%lluULL<<64)|(sda_u128)%lluULL)",(unsigned long long)(x>>64),(unsigned long long)x);}
static int make_dir(const char *p) { return mkdir(p,0777)==0 || errno==EEXIST ? 0 : -1; }
static void write_failure(const sda_config*c,mpfr_t lo,mpfr_t hi,uint64_t master,uint64_t seed,unsigned trials,const char*why,FILE*log){char dir[160],path[220];snprintf(dir,sizeof dir,"offline/generated/%s",c->parameter_set);if(make_dir("offline/generated")||make_dir(dir))return;snprintf(path,sizeof path,"%s/selected_report.txt",dir);FILE*f=fopen(path,"w");if(!f)return;fprintf(f,"parameter_set=%s\nepsilon_lower=",c->parameter_set);mpfr_out_str(f,10,0,lo,MPFR_RNDN);fprintf(f,"\nepsilon_upper=");mpfr_out_str(f,10,0,hi,MPFR_RNDN);fprintf(f,"\nmaster_seed=%llu\nparameter_seed=%llu\ntrials_completed=%u\ngeneration_status=not_found\nmain_failure_reason=%s\nnormalization_applied=false\ntrial_log:\n",(unsigned long long)master,(unsigned long long)seed,trials,why);rewind(log);int ch;while((ch=fgetc(log))!=EOF)fputc(ch,f);fclose(f);}
static int write_candidate(const sda_config *c,const sda_generation_result *r,
                           mpfr_t lo,mpfr_t hi,uint64_t master,uint64_t seed,
                           unsigned trial,FILE *log) {
    char dir[160],path[220]; snprintf(dir,sizeof dir,"offline/generated/%s",c->parameter_set);
    if(make_dir("offline/generated")||make_dir(dir))return -1;
    snprintf(path,sizeof path,"%s/selected_report.txt",dir); FILE*f=fopen(path,"w");if(!f)return -1;
    fprintf(f,"parameter_set=%s\nk=%d\nn=%zu\nepsilon_lower=",c->parameter_set,c->precision_k,r->n);mpfr_out_str(f,10,0,lo,MPFR_RNDN);fprintf(f,"\nepsilon_upper=");mpfr_out_str(f,10,0,hi,MPFR_RNDN);fprintf(f,"\nselected_epsilon=");mpfr_out_str(f,10,0,r->epsilon,MPFR_RNDN);
    fprintf(f,"\nmaster_seed=%llu\nparameter_seed=%llu\naccepted_trial=%u\ntrial_index=%u\nsolver=%s\nsolver_version=builtin-C17\nsolver_exact=%s\nheuristic_bkz=%s\nMPFR_precision=%lu\nq=",(unsigned long long)master,(unsigned long long)seed,trial,trial,r->solver,r->exact_linf_svp?"true":"false",r->heuristic?"true":"false",(unsigned long)c->mpfr_precision);print_u128(f,r->q);
    fprintf(f,"\np=");for(size_t i=0;i<r->n;i++){if(i)fputc(' ',f);print_u128(f,r->p[i]);}fprintf(f,"\ncumulative=");for(size_t i=0;i<r->n;i++){if(i)fputc(' ',f);print_u128(f,r->c[i]);}
    fprintf(f,"\nmax_pointwise_error=");mpfr_out_str(f,10,0,r->max_abs_error,MPFR_RNDN);mpfr_t target;mpfr_init2(target,c->mpfr_precision);mpfr_set_ui_2exp(target,1,-c->precision_k,MPFR_RNDN);fprintf(f,"\npointwise_target=");mpfr_out_str(f,10,0,target,MPFR_RNDN);fprintf(f,"\npointwise_target_met=%s",mpfr_cmp(r->max_abs_error,target)<=0?"true":"false");mpfr_clear(target);fprintf(f,"\nSD=");mpfr_out_str(f,10,0,r->sd_infinite,MPFR_RNDN);fprintf(f,"\nSD_baseline=");mpfr_out_str(f,10,0,r->baseline_sd_infinite,MPFR_RNDN);fprintf(f,"\nsd_baseline_met=%s",mpfr_nan_p(r->baseline_sd_infinite)||mpfr_zero_p(r->baseline_sd_infinite)?"not_applicable":(mpfr_cmp(r->sd_infinite,r->baseline_sd_infinite)<=0?"true":"false"));fprintf(f,"\nRD=");mpfr_out_str(f,10,0,r->renyi,MPFR_RNDN);fprintf(f,"\nRD_baseline=");mpfr_out_str(f,10,0,r->baseline_renyi,MPFR_RNDN);fprintf(f,"\nrd_baseline_met=%s",mpfr_nan_p(r->baseline_renyi)||mpfr_zero_p(r->baseline_renyi)?"not_applicable":(mpfr_cmp(r->renyi,r->baseline_renyi)<=0?"true":"false"));fprintf(f,"\nRenyi_order=%ld\nsum_p_equals_q=true\nq_below_2k=true\nsupport_valid=true\ninternal_zero_hole=false\nnormalization_applied=false\ngeneration_status=accepted\nfrozen_table_identical=false\ntrial_log:\n",c->renyi_order);rewind(log);int ch;while((ch=fgetc(log))!=EOF)fputc(ch,f);fclose(f);
    snprintf(path,sizeof path,"%s/selected_table.txt",dir);f=fopen(path,"w");if(!f)return -1;fprintf(f,"q=");print_u128(f,r->q);fprintf(f,"\np=");for(size_t i=0;i<r->n;i++){if(i)fputc(' ',f);print_u128(f,r->p[i]);}fputc('\n',f);fclose(f);
    snprintf(path,sizeof path,"%s/selected_table.h",dir);f=fopen(path,"w");if(!f)return -1;fprintf(f,"/* Candidate only; not promoted online. */\n#include \"sda_u128.h\"\nstatic const sda_u128 selected_q=");print_c_u128(f,r->q);fprintf(f,";\nstatic const sda_u128 selected_p[]={");for(size_t i=0;i<r->n;i++){if(i)fputc(',',f);print_c_u128(f,r->p[i]);}fprintf(f,"};\nstatic const sda_u128 selected_cumulative[]={");for(size_t i=0;i<r->n;i++){if(i)fputc(',',f);print_c_u128(f,r->c[i]);}fprintf(f,"};\n");fclose(f);return 0;
}
static int run_falcon(const sda_config*c,uint64_t master,uint64_t seed,unsigned max_trials,sda_epsilon_rng*rng,mpfr_t lo,mpfr_t hi,mpfr_t eps,FILE*log,const char*diagnostic_path){
 char version[128];if(!sda_falcon_bkz_available(version,sizeof version))return 2;FILE*diag=diagnostic_path?fopen(diagnostic_path,"w"):0;if(diag)fprintf(diag,"parameter_set,trial_index,epsilon,solver_return_code,q,sum_p,selected_basis_row,recoverable_rows,structurally_valid_rows,structural_reject_flags,quality_flags,accepted\n");
 for(unsigned t=1;t<=max_trials;t++){sda_epsilon_random(rng,lo,hi,eps);size_t n=19;mpfr_t a[32],tail,gs;for(size_t i=0;i<n;i++)mpfr_init2(a[i],c->mpfr_precision);mpfr_inits2(c->mpfr_precision,tail,gs,(mpfr_ptr)0);sda_generate_distribution(c,a,n,tail,gs);sda_falcon_bkz_result br;int rc=sda_falcon_bkz_solve(a,eps,c->mpfr_precision,seed+t,&br);unsigned structural=rc?SDA_REJECT_SOLVER:0,quality=0;sda_u128 sum=0;for(size_t i=0;i<n;i++)sum+=br.p[i];if(!rc){if(!br.q)structural|=SDA_REJECT_Q_ZERO;if(br.q>=((sda_u128)1<<72))structural|=SDA_REJECT_Q_LARGE;if(sum!=br.q)structural|=SDA_REJECT_SUM;}sda_metrics m;sda_metrics_init(&m,c->mpfr_precision);if(!structural){sda_compute_metrics(a,n,br.p,br.q,509,&m);mpfr_t plim,rdb;mpfr_inits2(c->mpfr_precision,plim,rdb,(mpfr_ptr)0);mpfr_set_ui_2exp(plim,1,-72,MPFR_RNDN);mpfr_set_ui_2exp(rdb,1,-78,MPFR_RNDN);mpfr_add_ui(rdb,rdb,1,MPFR_RNDN);if(mpfr_cmp(m.max_absolute_error,plim)>0)quality|=1u;if(mpfr_cmp(m.renyi,rdb)>0)quality|=4u;mpfr_clears(plim,rdb,(mpfr_ptr)0);}if(diag){fprintf(diag,"falcon,%u,",t);mpfr_out_str(diag,10,18,eps,MPFR_RNDN);fprintf(diag,",%d,",rc);print_u128(diag,br.q);fputc(',',diag);print_u128(diag,sum);fprintf(diag,",%d,%d,%d,0x%x,0x%x,%s\n",br.selected_basis_row,br.recoverable_row_count,br.structurally_valid_row_count,structural,quality,structural?"false":"true");}if(!structural){sda_generation_result out;sda_generation_result_init(&out,c->mpfr_precision);out.n=n;out.q=br.q;out.heuristic=1;strcpy(out.solver,"heuristic-bkz20");mpfr_set(out.epsilon,eps,MPFR_RNDN);for(size_t i=0;i<n;i++)out.p[i]=br.p[i];sda_build_cumulative(out.p,n,out.c,&out.q);mpfr_set(out.max_abs_error,m.max_absolute_error,MPFR_RNDN);mpfr_set(out.sd_infinite,m.sd_support,MPFR_RNDN);mpfr_set(out.renyi,m.renyi,MPFR_RNDN);fprintf(log,"falcon,%u,accepted,row=%d,recoverable=%d,valid=%d\n",t,br.selected_basis_row,br.recoverable_row_count,br.structurally_valid_row_count);int w=write_candidate(c,&out,lo,hi,master,seed,t,log);char rp[220];snprintf(rp,sizeof rp,"offline/generated/falcon/selected_report.txt");FILE*rf=fopen(rp,"a");if(rf){mpfr_t rt;mpfr_init2(rt,c->mpfr_precision);mpfr_set_ui_2exp(rt,1,-78,MPFR_RNDN);mpfr_add_ui(rt,rt,1,MPFR_RNDN);fprintf(rf,"heuristic_bkz=true\nexact_svp=false\nBKZ_block_size=20\nselected_basis_row=%d\nrecoverable_row_count=%d\nstructurally_valid_row_count=%d\nfalcon_RD_target=",br.selected_basis_row,br.recoverable_row_count,br.structurally_valid_row_count);mpfr_out_str(rf,10,0,rt,MPFR_RNDN);fprintf(rf,"\nfalcon_rd_target_met=%s\nfrozen_table_identical=false\n",mpfr_cmp(m.renyi,rt)<=0?"true":"false");mpfr_clear(rt);fclose(rf);}sda_generation_result_clear(&out);sda_metrics_clear(&m);for(size_t i=0;i<n;i++)mpfr_clear(a[i]);mpfr_clears(tail,gs,(mpfr_ptr)0);if(diag)fclose(diag);fprintf(stderr,"completed_trials=%u accepted_count=1 selected_basis_row=%d recoverable_rows=%d structurally_valid_rows=%d quality_flags=0x%x fplll_version=%s\n",t,br.selected_basis_row,br.recoverable_row_count,br.structurally_valid_row_count,quality,version);return w?1:0;}sda_metrics_clear(&m);for(size_t i=0;i<n;i++)mpfr_clear(a[i]);mpfr_clears(tail,gs,(mpfr_ptr)0);}if(diag)fclose(diag);return 2;}

int sda_random_generate_config(const char *path,uint64_t master,unsigned max_trials,const char *diagnostic_path){
    sda_config c;if(sda_config_load(path,&c))return 1;size_t n=(size_t)(c.support_max-c.support_min+1);uint64_t seed=sda_parameter_seed(master,c.parameter_set);sda_epsilon_rng rng;sda_epsilon_rng_init(&rng,seed);mpfr_t lo,hi,eps;mpfr_inits2(c.mpfr_precision,lo,hi,eps,(mpfr_ptr)0);sda_epsilon_bounds(c.precision_k,n,lo,hi);FILE*log=tmpfile();if(!log)return 1;
    if(!strcmp(c.scheme,"Falcon")) return run_falcon(&c,master,seed,max_trials,&rng,lo,hi,eps,log,diagnostic_path);
    FILE*diag=diagnostic_path?fopen(diagnostic_path,"w"):0;unsigned counts[11]={0},success=0,accepted=0;
    if(diag)fprintf(diag,"parameter_set,trial_index,epsilon,solver_return_code,solver_completed,q,q_bit_length,min_p,sum_p,sum_p_minus_q,terminal_cumulative,max_pointwise_error,pointwise_limit,SD,SD_baseline,RD,RD_baseline,support_valid,internal_zero_hole,structural_reject_flags,quality_flags,accepted\n");
    for(unsigned t=1;t<=max_trials;t++){sda_epsilon_random(&rng,lo,hi,eps);sda_candidate_diagnostic d;sda_candidate_diagnostic_init(&d,c.mpfr_precision);int rc=sda_diagnose_frodo_epsilon(&c,eps,&d);if(d.solver_completed)success++;for(int b=0;b<11;b++)if(d.reject_flags&(1u<<b))counts[b]++;if(!rc)accepted++;
      if(diag){fprintf(diag,"%s,%u,",c.parameter_set,t);mpfr_out_str(diag,10,18,eps,MPFR_RNDN);fprintf(diag,",%d,%s,",d.solver_rc,d.solver_completed?"true":"false");print_u128(diag,d.q);fprintf(diag,",%d,",d.q_bits);sda_u128 min=d.n?d.p[0]:0;for(size_t i=1;i<d.n;i++)if(d.p[i]<min)min=d.p[i];print_u128(diag,min);fputc(',',diag);print_u128(diag,d.sum);fprintf(diag,",%lld,",(long long)(d.sum-d.q));print_u128(diag,d.terminal);if(d.q&&!(d.reject_flags&(SDA_REJECT_Q_LARGE|SDA_REJECT_SUM))){fputc(',',diag);mpfr_out_str(diag,10,18,d.max_pointwise,MPFR_RNDN);fputc(',',diag);mpfr_out_str(diag,10,18,d.pointwise_limit,MPFR_RNDN);fputc(',',diag);mpfr_out_str(diag,10,18,d.sd,MPFR_RNDN);fputc(',',diag);mpfr_out_str(diag,10,18,d.sd_baseline,MPFR_RNDN);fputc(',',diag);mpfr_out_str(diag,10,18,d.rd,MPFR_RNDN);fputc(',',diag);mpfr_out_str(diag,10,18,d.rd_baseline,MPFR_RNDN);}else fprintf(diag,",unavailable,unavailable,unavailable,unavailable,unavailable,unavailable");fprintf(diag,",%s,%s,0x%x,0x%x,%s\n",(d.reject_flags&SDA_REJECT_SUPPORT)?"false":"true",(d.reject_flags&SDA_REJECT_ZERO_HOLE)?"true":"false",d.reject_flags,d.quality_flags,rc?"false":"true");}
      fprintf(log,"%s,%u,%llu,",c.parameter_set,t,(unsigned long long)seed);mpfr_out_str(log,10,18,eps,MPFR_RNDN);fprintf(log,",%d,%s,0x%x\n",d.solver_rc,rc?"reject":"accept",d.reject_flags);sda_candidate_diagnostic_clear(&d);if(!rc){sda_generation_result r;sda_generation_result_init(&r,c.mpfr_precision);sda_generate_for_epsilon(&c,eps,&r);int w=write_candidate(&c,&r,lo,hi,master,seed,t,log);sda_generation_result_clear(&r);if(diag)fclose(diag);fclose(log);mpfr_clears(lo,hi,eps,(mpfr_ptr)0);return w?1:0;}}
    if(diag)fclose(diag);
    fprintf(stderr,"completed_trials=%u solver_success=%u solver_failures=%u q_zero_count=%u q_too_large_count=%u negative_mass_count=%u sum_mismatch_count=%u cumulative_mismatch_count=%u support_failure_count=%u internal_zero_count=%u pointwise_failure_count=%u sd_failure_count=%u rd_failure_count=%u accepted_count=%u\n",max_trials,success,counts[0],counts[1],counts[2],counts[3],counts[4],counts[5],counts[6],counts[7],counts[8],counts[9],counts[10],accepted);
    write_failure(&c,lo,hi,master,seed,max_trials,"no_legal_solver_candidate",log);fprintf(stderr,"%s: generation_status=not_found after %u trials\n",c.parameter_set,max_trials);fclose(log);mpfr_clears(lo,hi,eps,(mpfr_ptr)0);return 2;
}
